const extractText = (item) => {
  if (item.candidates && item.candidates[0] && item.candidates[0].content && item.candidates[0].content.parts) {
    return item.candidates[0].content.parts[0].text || '';
  }
  if (item.choices && item.choices[0] && item.choices[0].message) {
    return item.choices[0].message.content || '';
  }
  if (item.content && item.content[0] && item.content[0].text) {
    return item.content[0].text || '';
  }
  if (item.response) {
    return item.response || '';
  }
  return '';
};

const originalItems = $('Parse Generate').all();
for (let i = 0; i < $input.all().length; i++) {
  const original = originalItems[i].json;
  const item = $input.all()[i];
  let rawText = extractText(item.json);
  let cleanText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
  let parsed = {};
  try { parsed = JSON.parse(cleanText); } catch(e) {}

  item.json = {
    ...original,
    humanized_resume_bullets: parsed.resume_bullets || original.resume_bullets,
    humanized_cover_letter: parsed.cover_letter || original.cover_letter,
    draft: cleanText
  };
}
return $input.all();

for(let item of $input.all()) {
  const text = item.json.draft || '';
  const clicheRegex = /\b(delve|moreover|furthermore|leverage|seamless|testament to|unlock|robust|tapestry|elevate|boast)\b/gi;
  const hits = (text.match(clicheRegex) || []).length;
  item.json.cliche_hits = hits;
  item.json.needs_rewrite = hits > 2;
}
return $input.all();

for(let item of $input.all()) {
  const jobDescription = item.json.description || '';
  const resumeBullets = item.json.resume_bullets || [];
  const words = jobDescription.split(/\W+/).filter(w => w.length > 4);
  const uniqueKeywords = [...new Set(words.map(w => w.toLowerCase()))];
  const resumeText = resumeBullets.join(' ').toLowerCase();
  if (uniqueKeywords.length === 0) {
    item.json.ats_coverage_pct = 100;
  } else {
    const covered = uniqueKeywords.filter(k => resumeText.includes(k));
    item.json.ats_coverage_pct = Math.round((covered.length / uniqueKeywords.length) * 100);
  }
}
return $input.all();

const fs = require('fs');
for (let item of $input.all()) {
  let profile = {};
  try { profile = JSON.parse(item.json.masterProfile || '{}'); } catch(e) {}
  const name = profile.name || 'Professional Candidate';
  const email = profile.contact && profile.contact.email ? profile.contact.email : '';
  const phone = profile.contact && profile.contact.phone ? profile.contact.phone : '';
  const location = profile.locations && profile.locations.length > 0 ? profile.locations[0] : '';
  const title = profile.target_titles && profile.target_titles.length > 0 ? profile.target_titles[0] : '';

  let bullets = item.json.humanized_resume_bullets || item.json.resume_bullets || [];
  if (typeof bullets === 'string') bullets = [bullets];
  if (!Array.isArray(bullets)) bullets = [];

  let bulletsHtml = bullets.map(b => `<li style="margin-bottom: 12px;">${b.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')}</li>`).join('\n');
  let contentHtml = `
    <div class="section">
      <h3 class="section-title">TAILORED EXPERIENCE</h3>
      <ul>
        ${bulletsHtml}
      </ul>
    </div>
  `;

  const htmlTemplate = `
