</head>
<body>
  <div class="container">
    <div class="header">
      <h1 class="name">${name}</h1>
      <h2 class="title">${title}</h2>
      <div class="contact-info">
        <span>${email}</span> | <span>${phone}</span> | <span>${location}</span>
