  item.json.hydrated_html = htmlTemplate;
  fs.writeFileSync('/data/hydrated.html', htmlTemplate);
}
return $input.all();

for (let item of $input.all()) {
  item.json.pdf_status = 'HTML generated successfully. Run `node scripts/html-to-pdf.js data/hydrated.html data/resume_final.pdf` locally on your host machine to convert it to a PDF, as the n8n Docker container does not contain Headless Chrome dependencies.';
